/**
 * [INPUT]: 依赖 ProviderStore、ProviderConnectionStore、SecretCipher、探测器、revision/audit 与 ID generator。
 * [OUTPUT]: 对外提供连接 CRUD、状态 CAS 与未保存/已保存连接探测。
 * [POS]: model/application 的真实上游路由用例；密钥只在此边界加解密。
 * [PROTOCOL]: 变更时更新此头部，然后检查 CLAUDE.md
 */
package com.owndsh.enterprise.model.application;

import com.owndsh.enterprise.audit.*;
import com.owndsh.enterprise.crypto.*;
import com.owndsh.enterprise.model.domain.*;
import com.owndsh.enterprise.model.persistence.*;
import com.owndsh.enterprise.revision.*;
import org.springframework.transaction.support.TransactionOperations;
import java.nio.*;import java.nio.charset.*;import java.time.*;import java.util.*;import java.util.function.LongSupplier;

public final class ProviderConnectionService {
    private static final String TABLE="ent_model_provider_connection", FIELD="credential_ciphertext";
    private final TransactionOperations tx;private final ProviderStore providers;private final ProviderConnectionStore connections;private final SecretCipher cipher;private final ProviderProbe probe;private final BootstrapRevisionStore revisions;private final AuditSink audit;private final LongSupplier ids;private final Clock clock;
    public ProviderConnectionService(TransactionOperations tx,ProviderStore providers,ProviderConnectionStore connections,SecretCipher cipher,ProviderProbe probe,BootstrapRevisionStore revisions,AuditSink audit,LongSupplier ids){this(tx,providers,connections,cipher,probe,revisions,audit,ids,Clock.systemUTC());}
    ProviderConnectionService(TransactionOperations tx,ProviderStore providers,ProviderConnectionStore connections,SecretCipher cipher,ProviderProbe probe,BootstrapRevisionStore revisions,AuditSink audit,LongSupplier ids,Clock clock){this.tx=tx;this.providers=providers;this.connections=connections;this.cipher=cipher;this.probe=probe;this.revisions=revisions;this.audit=audit;this.ids=ids;this.clock=clock;}
    public List<ProviderConnection> list(String tenant,long providerId,long after,int limit){providers.find(tenant,providerId).orElseThrow(ModelResourceNotFoundException::new);return connections.list(tenant,providerId,after,limit);}
    public ProviderConnection get(String tenant,long id){return connections.find(tenant,id).orElseThrow(ModelResourceNotFoundException::new);}
    public ProviderConnection create(ModelMutationContext context,long providerId,ProviderConnectionSpec spec,ProviderSecretInput secret){ModelProvider p=providers.find(context.tenantId(),providerId).orElseThrow(ModelResourceNotFoundException::new);long id=positive();ProviderConnection c=build(id,context.tenantId(),p,spec,encrypt(context.tenantId(),id,secret),ModelStatus.ACTIVE,null,0);return Objects.requireNonNull(tx.execute(s->{connections.insert(c);long r=revisions.increment(context.tenantId());audit(context,c,ProviderConnectionChangeMetadata.Operation.CREATE,true,r);return c;}));}
    public ProviderConnection update(ModelMutationContext context,long id,long expected,ProviderConnectionSpec spec,boolean replace,ProviderSecretInput replacement){ProviderConnection current=get(context.tenantId(),id);if(current.revision()!=expected)throw new RevisionConflictException(expected,current.revision());EncryptedSecret secret=replace?encrypt(context.tenantId(),id,replacement):current.encryptedCredential();ProviderConnection updated=new ProviderConnection(id,current.tenantId(),current.providerId(),current.providerName(),spec.name(),spec.apiProtocol(),spec.baseUrl(),spec.modelDiscoveryPath(),secret,current.status(),spec.connectTimeoutMs(),spec.readTimeoutMs(),current.lastProbeStatus(),expected+1);return Objects.requireNonNull(tx.execute(s->{if(!connections.update(updated,expected))throw new RevisionConflictException(expected,get(context.tenantId(),id).revision());long r=revisions.increment(context.tenantId());audit(context,updated,ProviderConnectionChangeMetadata.Operation.UPDATE,replace,r);return updated;}));}
    public ProviderConnection setStatus(ModelMutationContext context,long id,long expected,ModelStatus status){ProviderConnection c=get(context.tenantId(),id);if(c.revision()!=expected)throw new RevisionConflictException(expected,c.revision());ProviderConnection u=new ProviderConnection(c.id(),c.tenantId(),c.providerId(),c.providerName(),c.name(),c.apiProtocol(),c.baseUrl(),c.modelDiscoveryPath(),c.encryptedCredential(),status,c.connectTimeoutMs(),c.readTimeoutMs(),c.lastProbeStatus(),expected+1);return Objects.requireNonNull(tx.execute(s->{if(!connections.updateStatus(context.tenantId(),id,status,expected))throw new RevisionConflictException(expected,get(context.tenantId(),id).revision());long r=revisions.increment(context.tenantId());audit(context,u,status==ModelStatus.ACTIVE?ProviderConnectionChangeMetadata.Operation.ENABLE:ProviderConnectionChangeMetadata.Operation.DISABLE,false,r);return u;}));}
    public ProviderProbe.ProviderProbeResult test(String tenant,long id,ProviderSecretInput replacement){ProviderConnection c=get(tenant,id);char[] credential=chars(tenant,id,c.encryptedCredential(),replacement);try{return probe.probe(c.apiProtocol(),c.baseUrl(),c.modelDiscoveryPath(),credential,c.connectTimeoutMs(),c.readTimeoutMs());}finally{Arrays.fill(credential,'\0');}}
    public ProviderProbe.ProviderProbeResult probe(ProviderConnectionSpec spec,ProviderSecretInput secret){char[] credential=secret.value();try{return probe.probe(spec.apiProtocol(),spec.baseUrl(),spec.modelDiscoveryPath(),credential,spec.connectTimeoutMs(),spec.readTimeoutMs());}finally{Arrays.fill(credential,'\0');}}
    private ProviderConnection build(long id,String tenant,ModelProvider p,ProviderConnectionSpec s,EncryptedSecret secret,ModelStatus status,String probeStatus,long rev){return new ProviderConnection(id,tenant,p.id(),p.name(),s.name(),s.apiProtocol(),s.baseUrl(),s.modelDiscoveryPath(),secret,status,s.connectTimeoutMs(),s.readTimeoutMs(),probeStatus,rev);}
    private char[] chars(String tenant,long id,EncryptedSecret encrypted,ProviderSecretInput replacement){if(replacement!=null)return replacement.value();byte[] plain=cipher.decrypt(SecretPurpose.PROVIDER_SECRET,new SecretAad(tenant,TABLE,Long.toString(id),FIELD,SecretCipher.KEY_VERSION),encrypted);try{return decode(plain);}finally{Arrays.fill(plain,(byte)0);}}
    private EncryptedSecret encrypt(String tenant,long id,ProviderSecretInput input){if(input==null)throw new IllegalArgumentException("credential 不能为空");char[] c=input.value();byte[] plain=encode(c);try{return cipher.encrypt(SecretPurpose.PROVIDER_SECRET,new SecretAad(tenant,TABLE,Long.toString(id),FIELD,SecretCipher.KEY_VERSION),plain);}finally{Arrays.fill(c,'\0');Arrays.fill(plain,(byte)0);}}
    private static byte[] encode(char[] c){try{ByteBuffer b=StandardCharsets.UTF_8.newEncoder().encode(CharBuffer.wrap(c));byte[] out=new byte[b.remaining()];b.get(out);return out;}catch(CharacterCodingException e){throw new IllegalArgumentException("credential 编码非法",e);}}
    private static char[] decode(byte[] b){try{CharBuffer c=StandardCharsets.UTF_8.newDecoder().decode(ByteBuffer.wrap(b));char[] out=new char[c.remaining()];c.get(out);return out;}catch(CharacterCodingException e){throw new IllegalStateException("credential 编码非法",e);}}
    private long positive(){long id=ids.getAsLong();if(id<=0)throw new IllegalStateException("ID generator 必须返回正数");return id;}
    private void audit(ModelMutationContext c,ProviderConnection connection,ProviderConnectionChangeMetadata.Operation operation,boolean secretReplaced,long bootstrapRevision){audit.append(new AuditEvent(positive(),c.tenantId(),Instant.now(clock),AuditActorType.USER,c.actorId(),null,AuditAction.MODEL_CONNECTION_CHANGED,"MODEL_PROVIDER_CONNECTION",Long.toString(connection.id()),AuditResult.SUCCESS,null,c.requestId(),c.sourceIp(),c.userAgentHash(),new ProviderConnectionChangeMetadata(connection.id(),connection.providerId(),operation,secretReplaced,connection.revision(),bootstrapRevision)));}
}
